<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserMfaRecoveryCode\Domain\UserMfaRecoveryCode;

class UserMfaRecoveryCodeCursor
{
    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
    ) {
    }
    public function next(UserMfaRecoveryCode $userMfaRecoveryCode, ?int $size): UserMfaRecoveryCodeCursor
    {
        $next = clone $this;
        $next->sinceUid = $userMfaRecoveryCode->uid();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
}
